<script setup lang="ts">
import { computed,reactive,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { fetchPersonnel } from '../../api/account'
import { useBusinessRead } from '../../composables/useBusinessRead'
import PersonnelCard from '../../components/account/PersonnelCard.vue'
import {switchPersonnelCategory,selectPersonnelRole,pendingPersonnelQuery} from './personnel-navigation'
const route=useRoute(),router=useRouter(),form=reactive({keyword:'',role:'',reviewStatus:'',enabled:''})
const category=computed(()=>typeof route.query.category==='string'?route.query.category:'ALL'),page=computed(()=>Math.max(1,Number(route.query.page)||1))
const categories:Record<string,string>={ALL:'全部人员',REPORTER_UNFINISHED:'报修用户有未完结业务',REPORTER_COMPLETED:'报修用户有已完成工单',TECHNICIAN_UNFINISHED:'维修人员有未完结任务',TECHNICIAN_COMPLETED:'维修人员有已完成工单'}
const {data,loading,message,stale,load,clear}=useBusinessRead(()=>fetchPersonnel({category:category.value,page:page.value,pageSize:20,role:typeof route.query.role==='string'?route.query.role:undefined,reviewStatus:typeof route.query.reviewStatus==='string'?route.query.reviewStatus:undefined,enabled:route.query.enabled==='true'?true:route.query.enabled==='false'?false:undefined,keyword:typeof route.query.keyword==='string'?route.query.keyword:undefined}),undefined,{target:()=>route.fullPath})
watch(()=>route.fullPath,()=>{for(const key of ['keyword','role','reviewStatus','enabled']as const)form[key]=typeof route.query[key]==='string'?String(route.query[key]):'';clear();void load()},{immediate:true})
function navigate(query:Record<string,string>){void router.push({path:'/admin/personnel',query})}
function search(next=1){navigate({category:category.value,...(form.role?{role:form.role}:{}),...(form.reviewStatus&&(!form.role||form.role==='TECHNICIAN')?{reviewStatus:form.reviewStatus}:{}),...(form.enabled?{enabled:form.enabled}:{}),...(form.keyword?{keyword:form.keyword}:{}),page:String(next)})}
function turnPage(next:number){void router.push({path:route.path,query:{...route.query,page:String(next)}})}
function roleChanged(){navigate(selectPersonnelRole({...route.query,keyword:form.keyword,enabled:form.enabled},form.role))}
</script>
<template><div class="page-heading"><div><h1>人员管理</h1><p>全体分类可重叠，不能相加作为总人数。</p></div><button class="secondary" :disabled="loading" @click="load">刷新</button></div><p v-if="message" class="notice" role="alert">{{message}}{{stale?'；显示上次资料，请核对最新状态。':''}}</p><section class="card"><p>待审核维修人员：{{data?.pendingReviewCount??'读取中 / 未知'}}</p><button class="secondary" @click="navigate(pendingPersonnelQuery())">查看待审核人员</button><div class="actions"><button v-for="(label,key) in categories" :key="key" class="secondary" :aria-pressed="category===key" @click="navigate(switchPersonnelCategory(route.query,key))">{{label}}（{{key==='ALL'?data?.allPeopleTotal??'未知':data?.categoryCounts[key]??'未知'}}）</button></div><form class="filter-grid" @submit.prevent="search()"><label>角色<select v-model="form.role" @change="roleChanged"><option value="">全部角色</option><option value="REPORTER">报修用户</option><option value="TECHNICIAN">维修人员</option><option value="ADMIN">管理员</option></select></label><label>维修资格<select v-model="form.reviewStatus" :disabled="!!form.role&&form.role!=='TECHNICIAN'"><option value="">全部资格</option><option value="PENDING">待审核</option><option value="REJECTED">未通过</option><option value="APPROVED">已通过</option></select></label><label>账号状态<select v-model="form.enabled"><option value="">全部</option><option value="true">启用</option><option value="false">停用</option></select></label><label>姓名 / 账号 / 手机号<input v-model="form.keyword" maxlength="100"></label><div class="actions"><button type="submit" class="primary">查询</button><button type="button" class="secondary" @click="navigate({category:'ALL',page:'1'})">重置筛选</button></div></form><p v-if="data">当前条件 {{data.listTotal}} 人 / 全部 {{data.allPeopleTotal}} 人</p></section><p v-if="loading" role="status">正在读取人员…</p><p v-if="data&&!data.records.length" class="notice">当前条件暂无人员，可清除筛选。</p><PersonnelCard v-for="person in data?.records" :key="person.id" :person="person" :back="route.fullPath" :blocked="loading||stale" @changed="load"/><div v-if="data" class="actions"><button class="secondary" :disabled="page<=1||loading" @click="turnPage(page-1)">上一页</button><span>第 {{page}} 页</span><button class="secondary" :disabled="page*data.pageSize>=data.listTotal||loading" @click="turnPage(page+1)">下一页</button></div></template>
<style scoped>.filter-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px}.card{margin-bottom:16px}.actions{flex-wrap:wrap}</style>

